import React, { useState, useEffect, useRef } from "react";
import { Settings, Play, Pause, Volume2, Globe2, RotateCcw, CheckCircle2, Sparkles, SwitchCamera } from "lucide-react";
const LOGO_B64 =
"data:image/png;base64,";
const SPLASH_ICON_B64 =
  "data:image/png;base64,";

const LANGS = ["English", "Kannada", "Hindi", "Tamil", "Telugu", "Malayalam"];

const SENTENCES = {
  English: "I am hungry.",
  Kannada: "ನನಗೆ ಹಸಿವಾಗಿದೆ.",
  Hindi: "मुझे भूख लगी है।",
  Tamil: "எனக்கு பசிக்கிறது.",
  Telugu: "నాకు ఆకలిగా ఉంది.",
  Malayalam: "എനിക്ക് വിശക്കുന്നു.",
};

// Crops the logo image so only the icon glyph shows (hides the baked-in
// wordmark/tagline at the bottom) using an overflow-hidden container.
function LogoIcon({ size = 34, radius = 10 }) {
  const renderedSize = size * 1.7; // full square image rendered larger...
  const cropHeight = size; // ...then clipped down to just the icon zone
  return (
    <div
      style={{
        width: size,
        height: cropHeight,
        borderRadius: radius,
        overflow: "hidden",
        flexShrink: 0,
        boxShadow: "0 2px 8px rgba(10,10,40,0.25)",
      }}
    >
      <img
        src={LOGO_B64}
        alt="Signa"
        style={{
          width: renderedSize,
          height: renderedSize,
          display: "block",
          objectFit: "cover",
          objectPosition: "top",
          marginLeft: -(renderedSize - size) / 2,
        }}
      />
    </div>
  );
}

export default function SignaDemo() {
  const [screen, setScreen] = useState("splash"); // splash, camera, recording, processing, output
  const [checks, setChecks] = useState({ light: false, hand: false, rec: false });
  const [recState, setRecState] = useState("idle"); // idle, recording, paused
  const [popup, setPopup] = useState(null); // 'speak' | 'translate' | 'startover' | null
  const [speakLang, setSpeakLang] = useState("English");
  const [translateLang, setTranslateLang] = useState("Kannada");
  const [translated, setTranslated] = useState(null);
  const [spoken, setSpoken] = useState(false);
 const timers = useRef([]);
  const [cameraError, setCameraError] = useState(null);
  // Camera now lives on the SERVER (see main.py) — this guarantees
  // byte-for-byte identical processing to the proven-working desktop
  // script (prediction.py), with no browser capture/encoding step in
  // between. The frontend just displays whatever frame the backend
  // pushes over the websocket. Flip-camera doesn't apply anymore (one
  // physical webcam, owned server-side), so that button is now inert —
  // kept visually for layout parity, does nothing when clicked.
  const [cameraFrameSrc, setCameraFrameSrc] = useState(null);

  // ============================================================
  // REAL BACKEND WIRING
  // Change BACKEND_HOST if your FastAPI server isn't on localhost
  // (e.g. your machine's LAN IP when testing from a phone).
  // ============================================================
  const BACKEND_HOST = window.location.hostname || "localhost";
  const WS_URL = `ws://${BACKEND_HOST}:8000/ws`;
  const API_BASE = `http://${BACKEND_HOST}:8000`;
  const LANG_CODES = { English: "en", Kannada: "kn", Hindi: "hi", Tamil: "ta", Telugu: "te", Malayalam: "ml" };

  const wsRef = useRef(null);
  const [wordBuffer, setWordBuffer] = useState([]);
  const [sentence, setSentence] = useState("");
  const [translatedText, setTranslatedText] = useState("");
  const audioRef = useRef(null);

  // Open the websocket once, on mount, and keep it alive for the whole
  // session rather than reconnecting per-screen.
  useEffect(() => {
    connectWS();
    return () => {
      if (wsRef.current) wsRef.current.close();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const connectWS = () => {
    const socket = new WebSocket(WS_URL);
    socket.onopen = () => console.log("Signa: websocket connected");
    socket.onerror = (e) => console.error("Signa: websocket error", e);
    socket.onclose = () => {
      console.log("Signa: websocket closed, retrying in 2s");
      setTimeout(connectWS, 2000);
    };
    socket.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      handleServerMessage(msg);
    };
    wsRef.current = socket;
  };

  const handleServerMessage = (msg) => {
    if (msg.type === "status") {
      setChecks((c) => ({ ...c, light: msg.lighting_good, hand: msg.hand_detected, rec: !!msg.detecting }));
      if (msg.words) setWordBuffer(msg.words);
    } else if (msg.type === "camera_frame") {
      setCameraFrameSrc(msg.data);
    } else if (msg.type === "sentence") {
      setSentence(msg.sentence || "");
      setScreen("output");
    } else if (msg.type === "reset_ack") {
      setWordBuffer([]);
      setSentence("");
      setCameraFrameSrc(null);
    } else if (msg.type === "error") {
      setCameraError(msg.message || "Something went wrong.");
      alert(msg.message || "Server camera error.");
    }
  };

  const clearTimers = () => {
    timers.current.forEach(clearTimeout);
    timers.current = [];
  };

  useEffect(() => {
    if (screen === "splash") {
      const t = setTimeout(() => setScreen("camera"), 2000);
      return () => clearTimeout(t);
    }
  }, [screen]);

  // Real frame-capture loop: grabs a frame from the video element, sends it
  // to the backend over the websocket. Lighting/hand-detected checks come
  const beginRecording = () => {
    setChecks({ light: false, hand: false, rec: false });
    setWordBuffer([]);
    setCameraFrameSrc(null);
    setCameraError(null);
    setScreen("recording");
    setRecState("recording");
    // Camera now lives on the server — just tell it to start. No browser
    // camera permission needed at all anymore.
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: "start" }));
    } else {
      alert("Connection to the server was lost. Please refresh the page and try again.");
    }
  };

  // toggleCamera is now inert — kept only so the flip button in the UI
  // doesn't need to be removed. There's one physical webcam, owned by
  // the server; "front/back" doesn't apply to a laptop's built-in camera
  // anyway, and this architecture is for local testing, not phone use.
  const toggleCamera = () => {};

  // Start button: begins a fresh recording from the camera screen, but if a
  // recording is already underway (recording or paused) it asks for
  // confirmation instead of restarting silently.
  const handleStartClick = () => {
    if (recState === "idle") {
      beginRecording();
    } else if (recState === "paused") {
      // Resume — same "start" message; backend resumes detecting on an
      // already-open camera instead of reopening it.
      setRecState("recording");
      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify({ type: "start" }));
      }
    } else {
      setPopup("startover");
    }
  };

  // Pause button: tells the backend to stop buffering/predicting, but
  // keeps the camera open so the live preview keeps streaming.
  const handlePauseToggle = () => {
    if (recState === "recording") {
      setRecState("paused");
      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify({ type: "pause" }));
      }
    } else if (recState === "paused") {
      handleStartClick(); // resumes via the same "start" message path
    }
  };

  // Sends the accumulated word buffer to the backend for real sentence
  // formation (Groq). Screen transitions to "output" once the "sentence"
  // message comes back (see handleServerMessage).
  const generateSentence = () => {
    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
      alert("Connection to the server was lost. Please refresh the page and try again.");
      return;
    }
    setScreen("processing");
    wsRef.current.send(JSON.stringify({ type: "generate_sentence" }));
  };

 const startOver = () => {
    clearTimers();
    setChecks({ light: false, hand: false, rec: false });
    setRecState("idle");
    setWordBuffer([]);
    setSentence("");
    setTranslated(null);
    setTranslatedText("");
    setSpoken(false);
    setPopup(null);
    setScreen("camera");
    setCameraFrameSrc(null);
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: "start_over" }));
    }
  };

 useEffect(() => {
    return () => {
      clearTimers();
    };
  }, []);

  return (
    <div
      style={{
        "--purple": "#7C6FE0",
        "--purple-dark": "#5D4FCF",
        "--navy": "#0E1233",
        "--lav-bg": "#F3F1FB",
        "--peach": "#FDECD8",
        "--orange": "#E8935A",
        "--green": "#3FB86F",
        "--red": "#E85B4F",
        "--blue": "#5B8DEF",
        "--ink": "#231F35",
        "--muted": "#8B87A3",
       fontFamily: "'Inter', 'Segoe UI', sans-serif",
       background: "linear-gradient(180deg, #FBF9FF 0%, #F1EEFB 100%)",
       minHeight: "100vh",
       display: "flex",
       flexDirection: "column",
       alignItems: "center",
       padding: "0",
       boxSizing: "border-box",
      }}
    >
      <div
  style={{
    width: "100%",
    maxWidth: "none",
    minHeight: "100vh",
    background: "#fff",
    borderRadius: "0",
    boxShadow: "none",
    overflow: "hidden",
    position: "relative",
    border: "none",
  }}
>
        <StatusBar />
        {screen === "splash" && <Splash />}
        {screen !== "splash" && (
          <div style={{ padding: "14px 18px 22px" }}>
            <TopBar onSettings={() => {}} />
            {screen === "camera" && <CameraOff onStart={handleStartClick} />}
            {screen === "recording" && (
             <Recording
                checks={checks}
                recState={recState}
                wordBuffer={wordBuffer}
                onGenerate={generateSentence}
                onStartClick={handleStartClick}
                onPauseToggle={handlePauseToggle}
                cameraFrameSrc={cameraFrameSrc}
                onToggleCamera={toggleCamera}
                cameraError={cameraError}
              />
            )}
            {screen === "processing" && <Processing />}
            {screen === "output" && (
              <Output
                sentence={sentence}
                translated={translated}
                translatedText={translatedText}
                spoken={spoken}
                onSpeak={() => setPopup("speak")}
                onTranslate={() => setPopup("translate")}
                onStartOver={() => setPopup("startover")}
              />
            )}
          </div>
        )}

        {popup === "speak" && (
          <LangPopup
            title="Speak in"
            subtitle="Select a language"
            lang={speakLang}
            setLang={setSpeakLang}
            confirmLabel="Speak"
            confirmColor="var(--purple)"
            onCancel={() => setPopup(null)}
            onConfirm={async () => {
              setPopup(null);
              try {
                // gTTS only pronounces whatever text it's given — it
                // doesn't translate. So if the chosen speak language
                // isn't English, we need to translate the sentence
                // first, then speak the translated text. Previously
                // this always sent the original English sentence,
                // which just got read aloud with different phonetics
                // instead of actually being translated.
                let textToSpeak = sentence;
                if (speakLang !== "English") {
                  const translateRes = await fetch(`${API_BASE}/translate`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ text: sentence, language: speakLang }),
                  });
                  if (!translateRes.ok) throw new Error("Translate-before-speak failed: " + translateRes.status);
                  const translateData = await translateRes.json();
                  textToSpeak = translateData.translated_text;
                  // Also reflect this translation on the Output screen,
                  // so the UI stays consistent with what's about to be spoken.
                  setTranslatedText(textToSpeak);
                  setTranslated(speakLang);
                }

                const res = await fetch(`${API_BASE}/speak`, {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ text: textToSpeak, lang: LANG_CODES[speakLang] || "en" }),
                });
                if (!res.ok) throw new Error("Speak request failed: " + res.status);
                const blob = await res.blob();
                if (audioRef.current) {
                  audioRef.current.src = URL.createObjectURL(blob);
                  audioRef.current.play();
                }
                setSpoken(true);
              } catch (e) {
                console.error(e);
                alert("Speak failed: " + e.message);
              }
            }}
          />
        )}

        {popup === "translate" && (
          <LangPopup
            title="Translate to"
            subtitle="Select a language"
            lang={translateLang}
            setLang={setTranslateLang}
            confirmLabel="Translate"
            confirmColor="var(--blue)"
            onCancel={() => setPopup(null)}
            onConfirm={async () => {
              setPopup(null);
              try {
                const res = await fetch(`${API_BASE}/translate`, {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ text: sentence, language: translateLang }),
                });
                if (!res.ok) throw new Error("Translate request failed: " + res.status);
                const data = await res.json();
                setTranslatedText(data.translated_text);
                setTranslated(translateLang);
              } catch (e) {
                console.error(e);
                alert("Translate failed: " + e.message);
              }
            }}
          />
        )}

        {popup === "startover" && (
          <ConfirmPopup onCancel={() => setPopup(null)} onConfirm={startOver} />
        )}
        <audio ref={audioRef} style={{ display: "none" }} />
      </div>
    </div>
  );
}

function StatusBar() {
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "10px 20px 0",
        fontSize: "13px",
        fontWeight: 600,
        color: "var(--ink)",
      }}
    >
    </div>
  );
}

function TopBar({ onSettings }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
     <img
  src={LOGO_B64}
  alt="Signa"
  style={{ width: "34px", height: "34px", objectFit: "contain", borderRadius: "9px" }}
/>
    </div>
  );
}

function Splash() {
  const nameLetters = "SIGNA".split("");
  const tagline = "Where Signs Speak.";
  const letterDelay = 0.09; // seconds between each letter of "Signa"
  const nameDuration = nameLetters.length * letterDelay; // total time for name to finish
  const taglineDelay = nameDuration + 0.15; // tagline starts just after name finishes

  return (
    <div
      style={{
        height: "600px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        background: "linear-gradient(160deg, #0E1233 0%, #171C46 60%, #1B1440 100%)",
        fontFamily: "'Poppins', 'Inter', 'Segoe UI', sans-serif",
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@500;700;800&display=swap');
        @keyframes spin { to { transform: rotate(360deg); } }
        @keyframes letterPop {
          0% { opacity: 0; transform: translateY(14px) scale(0.6); }
          60% { opacity: 1; transform: translateY(-2px) scale(1.08); }
          100% { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes taglineFade {
          0% { opacity: 0; transform: translateY(6px); }
          100% { opacity: 1; transform: translateY(0); }
        }
        .signa-letter {
          display: inline-block;
          opacity: 0;
          animation: letterPop 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
        }
        .signa-tagline {
          opacity: 0;
          animation: taglineFade 0.5s ease-out forwards;
        }
      `}</style>

      <img
        src={SPLASH_ICON_B64}
        alt="Signa"
        style={{
          width: "128px",
          height: "128px",
          objectFit: "contain",
          marginBottom: "18px",
          filter: "drop-shadow(0 10px 24px rgba(80,60,180,0.35))",
        }}
      />

      <div style={{ fontSize: "32px", fontWeight: 800, letterSpacing: "-0.3px" }}>
        {nameLetters.map((letter, i) => (
          <span
            key={i}
            className="signa-letter"
            style={{
              animationDelay: `${i * letterDelay}s`,
              background: "linear-gradient(90deg, #4FC3F7, #9C7BEA, #F06AB0)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              backgroundClip: "text",
            }}
          >
            {letter}
          </span>
        ))}
      </div>

      <div
        className="signa-tagline"
        style={{
          fontSize: "13px",
          fontWeight: 500,
          color: "#A9A6C9",
          marginTop: "6px",
          animationDelay: `${taglineDelay}s`,
        }}
      >
        {tagline}
      </div>

      <div style={{ marginTop: "40px", width: "22px", height: "22px", border: "3px solid rgba(255,255,255,0.15)", borderTopColor: "#9C7BEA", borderRadius: "50%", animation: "spin 0.9s linear infinite" }} />
    </div>
  );
}

// Only Start and Pause remain — Stop was removed. Pause doubles as
// Resume once the recording is paused.
function ControlButtons({ recState, onStart, onPauseToggle }) {
  const isPaused = recState === "paused";
  const canPause = recState !== "idle";
  return (
    <div style={{ display: "flex", justifyContent: "center", gap: "56px", marginTop: "16px" }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "5px" }}>
        <div
          onClick={onStart}
          style={{
            width: "44px",
            height: "44px",
            borderRadius: "50%",
            background: "var(--green)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            cursor: "pointer",
          }}
        >
          <Play size={18} color="#fff" fill="#fff" />
        </div>
        <span style={{ fontSize: "11px", color: "var(--muted)" }}>Start</span>
      </div>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "5px" }}>
        <div
          onClick={canPause ? onPauseToggle : undefined}
          style={{
            width: "44px",
            height: "44px",
            borderRadius: "50%",
            background: canPause ? (isPaused ? "var(--purple)" : "#EDEBF7") : "#F4F2FA",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            cursor: canPause ? "pointer" : "default",
          }}
        >
          {isPaused ? (
            <Play size={18} color="#fff" fill="#fff" />
          ) : (
            <Pause size={18} color={canPause ? "#9B96B8" : "#D3D0E4"} />
          )}
        </div>
        <span style={{ fontSize: "11px", color: "var(--muted)" }}>{isPaused ? "Resume" : "Pause"}</span>
      </div>
    </div>
  );
}

function CameraOff({ onStart }) {
  return (
    <div>
      <div
        style={{
          height: "230px",
          background: "#F4F2FA",
          borderRadius: "16px",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: "10px",
        }}
      >
        <div style={{ position: "relative", width: "34px", height: "34px" }}>
          <div style={{ width: "34px", height: "34px", borderRadius: "8px", border: "2px solid #B9B4D2" }} />
          <div style={{ position: "absolute", top: "16px", left: "-3px", width: "40px", height: "2px", background: "#B9B4D2", transform: "rotate(-45deg)" }} />
        </div>
        <div style={{ color: "#8B87A3", fontSize: "13.5px", fontWeight: 600 }}>Camera is OFF</div>
        <div style={{ color: "#B4B0C8", fontSize: "12px" }}>Tap Start to begin</div>
      </div>
      <ControlButtons recState="idle" onStart={onStart} onPauseToggle={() => {}} />
      <button
        disabled
        style={{
          width: "100%",
          marginTop: "14px",
          padding: "11px",
          borderRadius: "12px",
          border: "none",
          background: "#EDEAF8",
          color: "#A29CC4",
          fontWeight: 600,
          fontSize: "13.5px",
        }}
      >
        Generate Sentence
      </button>
      <TipBox />
    </div>
  );
}

function TipBox() {
  return (
    <div style={{ marginTop: "14px", background: "#FDF6E9", borderRadius: "12px", padding: "12px 14px", display: "flex", flexDirection: "column", gap: "8px" }}>
      <div style={{ display: "flex", gap: "8px", fontSize: "12px", color: "#8B7A45" }}>
        <span>💡</span>
        <span>Make sure you are in a well lit environment</span>
      </div>
      <div style={{ display: "flex", gap: "8px", fontSize: "12px", color: "#8B7A45" }}>
        <span>🖐️</span>
        <span>Position your hand clearly within the frame</span>
      </div>
    </div>
  );
}

function Recording({ checks, recState, wordBuffer = [], onGenerate, onStartClick, onPauseToggle, cameraFrameSrc, onToggleCamera, cameraError }) {
  // Generate Sentence should be enabled once real words have been
  // recognized — not just once the fake light/hand/rec flags all flip true.
  const allDone = wordBuffer.length > 0;
  const isPaused = recState === "paused";
  return (
    <div>
      <div
        style={{
          width: "100%",
          aspectRatio: "16/10",
          maxHeight: "350px",
          borderRadius: "16px",
          background: "linear-gradient(160deg, #6B6B8C, #3E3E5C)",
          position: "relative",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          overflow: "hidden",
        }}
      >
        {cameraError ? (
          <div style={{ color: "#E8C9C9", fontSize: "12px", textAlign: "center", padding: "0 20px" }}>{cameraError}</div>
        ) : (
          <>
            {/* Camera now lives on the server (see main.py) — this <img>
                just displays whatever frame the backend pushes over the
                websocket. Guarantees the recognition pipeline sees the
                exact same raw frames it's showing you, with zero
                browser-side capture/encoding differences. */}
            {cameraFrameSrc ? (
              <img
                src={cameraFrameSrc}
                alt="Live camera feed"
                style={{ width: "100%", height: "100%", objectFit: "contain" }}
              />
            ) : (
              <div style={{ color: "#B9B6D8", fontSize: "12px" }}>Starting camera...</div>
            )}
          </>
        )}

        <div style={{ position: "absolute", top: "10px", left: "10px", background: "#1C1C2E", color: "#fff", fontSize: "11px", fontWeight: 700, padding: "3px 8px", borderRadius: "6px", display: "flex", alignItems: "center", gap: "4px" }}>
          <span style={{ width: "6px", height: "6px", borderRadius: "50%", background: isPaused ? "#8B87A3" : "var(--red)", display: "inline-block" }} />
          {isPaused ? "PAUSED" : "REC"}
        </div>
        <div
          onClick={onToggleCamera}
          style={{ position: "absolute", top: "10px", right: "10px", background: "rgba(28,28,46,0.8)", width: "30px", height: "30px", borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}
        >
          <SwitchCamera size={15} color="#fff" />
        </div>
      </div>

      <ControlButtons recState={recState} onStart={onStartClick} onPauseToggle={onPauseToggle} />
      <button
        onClick={onGenerate}
        disabled={!allDone}
        style={{
          width: "100%",
          marginTop: "14px",
          padding: "11px",
          borderRadius: "12px",
          border: "none",
          background: allDone ? "var(--purple)" : "#EDEAF8",
          color: allDone ? "#fff" : "#A29CC4",
          fontWeight: 600,
          fontSize: "13.5px",
          cursor: allDone ? "pointer" : "default",
          transition: "all 0.25s",
        }}
      >
        Generate Sentence
      </button>
      <div style={{ marginTop: "10px", fontSize: "12.5px", color: "var(--purple-dark)", background: "#F1EEFB", borderRadius: "10px", padding: "8px 12px", minHeight: "16px" }}>
        {wordBuffer.length ? wordBuffer.join(" ") : "No signs recognized yet"}
      </div>
      <div style={{ marginTop: "10px", background: "#EEFAF1", borderRadius: "12px", padding: "12px 14px", display: "flex", flexDirection: "column", gap: "8px" }}>
        <CheckRow label="Lighting: Good" done={checks.light} />
        <CheckRow label="Hand Detected" done={checks.hand} />
        <CheckRow label={isPaused ? "Recording paused" : checks.rec ? "Recording... Recognizing gestures..." : "Recording..."} done={checks.rec} />
      </div>
    </div>
  );
}

function CheckRow({ label, done }) {
  return (
    <div style={{ display: "flex", gap: "8px", fontSize: "12px", color: "#3E8B5C", alignItems: "flex-start" }}>
      {done ? <CheckCircle2 size={14} style={{ marginTop: "1px", flexShrink: 0 }} /> : <div style={{ width: "14px", height: "14px", borderRadius: "50%", border: "2px solid #BFE3CB", marginTop: "1px", flexShrink: 0 }} />}
      <span>{label}</span>
    </div>
  );
}

function Processing() {
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "40px 0" }}>
      <div
        style={{
          width: "88px",
          height: "88px",
          borderRadius: "50%",
          border: "4px solid #E6E2F7",
          borderTopColor: "var(--purple)",
          borderRightColor: "#E8A9C9",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          animation: "spin 1.1s linear infinite",
          marginBottom: "22px",
        }}
      >
        <Sparkles size={28} color="var(--purple)" />
      </div>
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      <div style={{ fontWeight: 700, fontSize: "17px", color: "var(--ink)", textAlign: "center" }}>Generating Sentence...</div>
      <div style={{ fontSize: "12.5px", color: "var(--muted)", marginTop: "6px" }}>Please wait a moment</div>
      <div style={{ marginTop: "24px", width: "100%", background: "#F1EEFB", borderRadius: "12px", padding: "12px 14px", display: "flex", gap: "8px", alignItems: "center" }}>
        <div style={{ width: "14px", height: "14px", border: "2px solid #C9C1F0", borderTopColor: "var(--purple)", borderRadius: "50%", animation: "spin 0.8s linear infinite" }} />
        <div style={{ fontSize: "12px", color: "#6B5FB0" }}>
          Processing...<br />
          <span style={{ color: "#9891C4" }}>Analyzing gestures and forming sentence...</span>
        </div>
      </div>
    </div>
  );
}

function Output({ sentence, translated, translatedText, spoken, onSpeak, onTranslate, onStartOver }) {
  return (
    <div>
      <div style={{ border: "1px solid #ECE9F8", borderRadius: "16px", padding: "16px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <span style={{ fontSize: "12px", color: "var(--muted)" }}>Original Sentence</span>
          <Volume2 size={15} color={spoken ? "var(--purple)" : "#C9C5DE"} />
        </div>
        <div style={{ fontSize: "19px", fontWeight: 700, color: "var(--ink)", marginTop: "8px" }}>{sentence || "(no words recognized)"}</div>
        <div style={{ borderTop: "1px solid #F0EEF7", margin: "14px 0" }} />
        <div style={{ fontSize: "12px", color: "var(--muted)" }}>{translated ? `Translation (${translated})` : "Translation"}</div>
        <div style={{ fontSize: translated ? "17px" : "13.5px", fontWeight: translated ? 700 : 400, color: translated ? "var(--blue)" : "#C4C0D8", marginTop: "8px" }}>
          {translated ? translatedText : "Not translated yet"}
        </div>
      </div>
      <div style={{ display: "flex", gap: "10px", marginTop: "16px" }}>
        <ActionButton icon={Volume2} label="Speak" bg="#EDEAFB" color="var(--purple-dark)" onClick={onSpeak} />
        <ActionButton icon={Globe2} label="Translate" bg="#E9F1FE" color="var(--blue)" onClick={onTranslate} />
      </div>
      <button
        onClick={onStartOver}
        style={{
          width: "100%",
          marginTop: "12px",
          padding: "12px",
          borderRadius: "12px",
          border: "none",
          background: "var(--peach)",
          color: "var(--orange)",
          fontWeight: 700,
          fontSize: "13.5px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: "7px",
          cursor: "pointer",
        }}
      >
        <RotateCcw size={15} /> Start Over
      </button>
    </div>
  );
}

function ActionButton({ icon: Icon, label, bg, color, onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        flex: 1,
        padding: "12px",
        borderRadius: "12px",
        border: "none",
        background: bg,
        color,
        fontWeight: 700,
        fontSize: "13.5px",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: "7px",
        cursor: "pointer",
      }}
    >
      <Icon size={15} /> {label}
    </button>
  );
}

function PopupShell({ children }) {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: "rgba(35,31,53,0.45)",
        display: "flex",
        alignItems: "flex-end",
        borderRadius: "34px",
        overflow: "hidden",
      }}
    >
      <div style={{ width: "100%", background: "#fff", borderRadius: "22px 22px 0 0", padding: "22px 20px 26px", boxSizing: "border-box", maxHeight: "82%", overflowY: "auto" }}>
        {children}
      </div>
    </div>
  );
}

function LangPopup({ title, subtitle, lang, setLang, confirmLabel, confirmColor, onCancel, onConfirm }) {
  const isSpeak = title === "Speak in";
  return (
    <PopupShell>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginBottom: "14px" }}>
        <div
          style={{
            width: "46px",
            height: "46px",
            borderRadius: "50%",
            background: isSpeak ? "#EDEAFB" : "#E9F1FE",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            marginBottom: "10px",
          }}
        >
          {isSpeak ? <Volume2 size={20} color="var(--purple)" /> : <Globe2 size={20} color="var(--blue)" />}
        </div>
        <div style={{ fontWeight: 700, fontSize: "15.5px", color: "var(--ink)" }}>{title}</div>
        <div style={{ fontSize: "12px", color: "var(--muted)" }}>{subtitle}</div>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: "2px", marginBottom: "16px" }}>
        {LANGS.map((l) => (
          <label key={l} style={{ display: "flex", alignItems: "center", gap: "10px", padding: "8px 4px", cursor: "pointer", fontSize: "14px", color: "var(--ink)" }}>
            <input type="radio" checked={lang === l} onChange={() => setLang(l)} style={{ accentColor: confirmColor }} />
            {l}
          </label>
        ))}
      </div>
      <div style={{ display: "flex", gap: "10px" }}>
        <button onClick={onCancel} style={{ flex: 1, padding: "11px", borderRadius: "11px", border: "none", background: "#F1EEFB", color: "#8B87A3", fontWeight: 600, fontSize: "13.5px" }}>
          Cancel
        </button>
        <button onClick={onConfirm} style={{ flex: 1, padding: "11px", borderRadius: "11px", border: "none", background: confirmColor, color: "#fff", fontWeight: 700, fontSize: "13.5px" }}>
          {confirmLabel}
        </button>
      </div>
    </PopupShell>
  );
}

function ConfirmPopup({ onCancel, onConfirm }) {
  return (
    <PopupShell>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginBottom: "16px" }}>
        <div style={{ width: "46px", height: "46px", borderRadius: "50%", background: "var(--peach)", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: "10px" }}>
          <RotateCcw size={20} color="var(--orange)" />
        </div>
        <div style={{ fontWeight: 700, fontSize: "16px", color: "var(--ink)" }}>Start New Input?</div>
        <div style={{ fontSize: "12.5px", color: "var(--muted)", textAlign: "center", marginTop: "4px" }}>
          The current recording and generated sentence will be cleared.
        </div>
      </div>
      <div style={{ display: "flex", gap: "10px" }}>
        <button onClick={onCancel} style={{ flex: 1, padding: "11px", borderRadius: "11px", border: "none", background: "#F1EEFB", color: "#8B87A3", fontWeight: 600, fontSize: "13.5px" }}>
          Cancel
        </button>
        <button onClick={onConfirm} style={{ flex: 1, padding: "11px", borderRadius: "11px", border: "none", background: "var(--orange)", color: "#fff", fontWeight: 700, fontSize: "13.5px" }}>
          Yes, Start Over
        </button>
      </div>
    </PopupShell>
  );
}